Here's the code in C++ that separates even and odd nodes in a linked list:

```cpp
#include <iostream>

class Node {
public:
    int data;
    Node *next;
    Node(int val) {
        data = val;
        next = nullptr;
    }
};

Node* divide(Node* head) {
    Node* resStart = nullptr;
    Node* resEnd = nullptr;
    Node* curr = head;
    Node* prev = nullptr;

    while (curr != nullptr) {
        if (curr->data % 2 == 0) {
            if (prev != nullptr) {
                prev->next = curr->next;
            } else {
                head = curr->next;
            }
            if (resStart == nullptr) {
                resStart = curr;
                resEnd = resStart;
            } else {
                resEnd->next = curr;
                resEnd = resEnd->next;
            }
            curr = curr->next;
        } else {
            prev = curr;
            curr = curr->next;
        }
    }

    if (resStart == nullptr) {
        return head;
    }

    resEnd->next = head;
    return resStart;
}

void printList(Node* node) {
    while (node != nullptr) {
        std::cout << node->data;
        if (node->next != nullptr) {
            std::cout << " -> ";
        }
        node = node->next;
    }
}

int main() {
    Node* head = new Node(0);
    head->next = new Node(1);
    head->next->next = new Node(4);
    head->next->next->next = new Node(6);
    head->next->next->next->next = new Node(9);
    head->next->next->next->next->next = new Node(10);
    head->next->next->next->next->next->next = new Node(11);

    std::cout << "Original Linked list: ";
    printList(head);

    head = divide(head);

    std::cout << "\nModified Linked list: ";
    printList(head);

    return 0;
}
```

This code separates even and odd nodes in a linked list and prints the modified list. It first checks if the current node is even, and if it is, it removes the node from the original list and adds it to the result list. If the current node is odd, it just moves to the next node. Finally, it appends the remaining original list (odd nodes) to the result list and returns the result list.

class Solution:
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next

    def solve(self, head):
        if not head:
            return head

        even_head = ListNode(0)
        odd_head = ListNode(0)
        even_tail = even_head
        odd_tail = odd_head
        current = head

        while current:
            if current.val % 2 == 0:
                even_tail.next = current
                even_tail = even_tail.next
            else:
                odd_tail.next = current
                odd_tail = odd_tail.next
            current = current.next

        even_tail.next = odd_head.next
        odd_tail.next = None

        return even_head.next
